package com.bank.token;

import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class PrimeDemo {

    private static final Logger log = Logger.getLogger(PrimeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        TokenValidator validator = new TokenValidator();

        for (int candidate : new int[]{1, 2, 17, 18, 97, 100, 7919}) {
            boolean prime = validator.isPrime(candidate);
            log.info(() -> "Token " + candidate + " is prime? " + prime);
        }

        log.info(() -> "Primes between 1 and 30: " + validator.primesUpTo(30));
    }
}

