class TokenValidator {

    private static final Logger log = Logger.getLogger(TokenValidator.class.getName());

    // Efficient primality: test divisors up to sqrt(n), odd-only after 2.
    boolean isPrime(int n) {
        if (n < 2) return false;            // 0 and 1 are not prime
        if (n == 2) return true;            // 2 is the only even prime
        if (n % 2 == 0) return false;       // other even numbers are not prime
        // Only odd divisors from 3; stop at sqrt(n) via i <= n/i (overflow-safe).
        for (int i = 3; i <= n / i; i += 2) {
            if (n % i == 0) {
                final int d = i;
                log.fine(() -> n + " divisible by " + d + " → not prime");
                return false;
            }
        }
        return true;                        // no divisor found → prime
    }

    // List all primes from 2 up to limit (uses isPrime).
    java.util.List<Integer> primesUpTo(int limit) {
        java.util.List<Integer> primes = new java.util.ArrayList<>();
        for (int i = 2; i <= limit; i++) {
            if (isPrime(i)) primes.add(i);
        }
        return primes;
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("[%1$tF %1$tT] %2$-7s %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                formatMessage(record));
    }
}
